using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class FogControlOperations:RefCounted
{
    private readonly FogCloudPresetsOperations _cloud=new();private readonly FogAppearanceOperations _appearance=new();private readonly ActorDataOperations _data=new();
    public void layer_actions(Control host,Resource actor,Resource target,Resource property,VBoxContainer parent)
    {
        string key=property.Get("id").AsString();int index=int.TryParse(key.TrimPrefix("layer_"),out int parsed)?parsed:0;var row=new HBoxContainer();parent.AddChild(row);foreach(int direction in new[]{-1,1}){var button=new Button{Text=direction<0?"↑":"↓",TooltipText="Move appearance influence",Disabled=index+direction<0||index+direction>3};row.AddChild(button);button.Pressed+=()=>{string other="layer_"+(index+direction);var a=target.Call("get_value",property.Get("id"),default(Variant));var b=target.Call("get_value",new StringName(other),default(Variant));var model=host.Get("model").As<RefCounted>();var history=model.Get("history").As<UndoRedo>();var action=new FogPropertyHistoryAction(model,target,new Settings{[key]=a,[other]=b},new Settings{[key]=b,[other]=a},true);history.CreateAction("Reorder fog influences");history.AddDoMethod(new Callable(action,"restore_after"));history.AddUndoMethod(new Callable(action,"restore_before"));history.AddDoReference(action);history.CommitAction();host.Call("_queue_rebuild_selected");};}
    }
    public void setup(VBoxContainer owner,Control host,Resource actor)
    {
        var atmosphere=new HBoxContainer();owner.AddChild(atmosphere);var presets=new OptionButton{FitToLongestItem=false,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,TooltipText="Clouds, mist and atmosphere · retains painted density as a mask"};atmosphere.AddChild(presets);foreach(var title in GD.Load<GDScript>("res://scripts/actors/fog/fog_cloud_presets.gd").GetScriptConstantMap()["TITLES"].AsGodotArray())presets.AddItem(title.AsString());var create=new Button{Text="Set atmosphere"};atmosphere.AddChild(create);create.Pressed+=()=>{_cloud.apply(host.Get("model").As<RefCounted>(),actor,presets.Selected);host.Call("_queue_rebuild_selected");};var row=new HBoxContainer();owner.AddChild(row);var choice=new OptionButton{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,FitToLongestItem=false};row.AddChild(choice);foreach(var title in GD.Load<GDScript>("res://scripts/actors/fog/fog_appearance.gd").GetScriptConstantMap()["PRESETS"].AsGodotArray())choice.AddItem(title.AsString());var apply=new Button{Text="Apply"};row.AddChild(apply);apply.Pressed+=()=>{var definition=host.Get("registry").AsGodotObject().Call("get_definition",actor.Get("type_id"));host.Call("_edit_property",actor,definition,new StringName("appearance"),_data.from_object(_appearance.preset(choice.Selected)));host.Call("_queue_rebuild_selected");};var info=new Label{Text="Appearance presets preserve volume shape and painted density.\nCustom fog shaders bypass built-in appearance.\nScattering direction is in World Environment.",AutowrapMode=TextServer.AutowrapMode.WordSmart};info.AddThemeFontSizeOverride("font_size",12);owner.AddChild(info);if(RenderingServer.GetCurrentRenderingMethod()!="forward_plus")info.Text="Volumetric fog requires the Forward+ renderer.\n"+info.Text;var status=new Label{AutowrapMode=TextServer.AutowrapMode.WordSmart,Modulate=new Color("ffce83")};owner.AddChild(status);host.Get("_updaters").AsGodotArray().Add(Callable.From(()=>Update(host,actor,status)));
    }
    private static void Update(Control host,Resource actor,Label status)
    {
        if(!GodotObject.IsInstanceValid(host)||!GodotObject.IsInstanceValid(status))return;foreach(var editor in host.GetTree().GetNodesInGroup("actor_timeline_editors")){var model=host.Get("model").AsGodotObject();if(editor.Get("model").AsGodotObject()!=model)continue;var clip=model.Call("clip_for_actor_id",actor.Get("id")).As<Resource>();if(clip==null)continue;var runtime=editor.Call("_runtime_for_clip",clip.Get("id")).As<Node>();if(runtime?.Get("content").AsGodotObject() is FogVolume fog)status.Text=(fog.GetMeta("fog_boundary_error","").AsString()+"\n"+fog.GetMeta("fog_ground_error","").AsString()).Trim();}
    }
}
